What does this program print when compiled and run?
int main(void) {
    printf("Hello, world!\n");
    return 0;
}

What does this print?
int a = 7, b = 2;
printf("%d\n", a / b);

What does this print?
int i = 10;
do {
    printf("%d\n", i);
    i++;
} while (i < 5);

What does this print for the "Outside" line?
void increment(int n) {
    n = n + 1;
}
int main(void) {
    int x = 5;
    increment(x);
    printf("Outside: %d\n", x);
}

What does this print?
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
int main(void) {
    int x = 5, y = 10;
    swap(&x, &y);
    printf("x=%d, y=%d\n", x, y);
}

What does this print?
int numbers[] = {10, 20, 30, 40};
printf("%d\n", *(numbers + 1));

